from lib import *
S = SS('n24')
steps = [
    step("responseWriter 嵌入一个 http.ResponseWriter,另有 size 和 status 两个字段。reset 把 size 置为 -1(noWritten)、status 置为 200;WriteHeader 只在没写出时记录状态(已经写出就忽略,debug 模式下打印警告);WriteHeaderNow 在没写出时把 size 置 0 并真正调用底层的 WriteHeader;Write 先 WriteHeaderNow 再写,并累加 size。Written() 的判断就是 size != -1。", t=tl(S(1)), mark=lidx(S(1), 'w.size = noWritten', 'w.status = defaultStatus', 'w.size = 0', 'w.size += n'), done=lidx(S(1), 'func (w *responseWriter) WriteHeader(code int)', 'w.WriteHeaderNow()', 'w.ResponseWriter.WriteHeader(w.status)'), kv=KV([['size = -1', '还没写出'], ['WriteHeader', '只记录状态(没写出时)'], ['WriteHeaderNow', 'size 置 0,才真正发状态行']], ['size = -1'])),
    step("一次请求里 Status / Size / Written 的变化:handler 刚进入 200 / -1 / false;c.Header 不改变它们;c.Status(201) → 201;再 c.Status(202) → 202(还没写,可以改);WriteHeaderNow() → Size=0、Written=true,状态锁定在 202;再 c.Status(500) 无效;WriteString(\"hello\") → Size=5;Write(\" world\") → Size=11。最终客户端:202,正文 hello world。", t=tl(S(2)), mark=lidx(S(2), 'c.Writer.WriteHeaderNow()', '再 c.Status(500)'), done=lidx(S(2), 'handler 刚进入', 'WriteString("hello")', 'Write(" world")', '最终客户端'), b=bars([['handler 刚进入', 0, 'Size=-1'], ['WriteHeaderNow()', 0, 'Size=0'], ['WriteString("hello")', 5, 'Size=5'], ['Write(" world")', 11, 'Size=11']], 11, done=[0, 1], mark=[2, 3]), kv=KV([['Size', '-1 → 0 → 5 → 11'], ['状态', '写出之前随便改,写出之后锁定'], ['Written()', 'WriteHeaderNow 之后就是 true']], ['状态'])),
    step("状态已发出后再改:release 模式静默忽略;debug 模式会打印 [GIN-debug] [WARNING] Headers were already written. Wanted to override status code 200 with 500(c.String 之后再 c.Status(500) 触发)。", t=tl(S(3)), mark=lidx(S(3), 'Headers were already written'), done=lidx(S(3), '[GIN-debug] GET'), kv=KV([['release', '静默忽略'], ['debug', 'WARNING: Wanted to override status code 200 with 500']], ['debug'])),
    step("包装 ResponseWriter 抓响应体:嵌入 gin.ResponseWriter 并只覆盖 Write 时,c.String、c.JSON、c.Data 的内容都能抓到,但 c.Writer.WriteString 和 io.WriteString(c.Writer, …) 抓到的是空——它们不经过 Write(WriteString 是接口里单独的方法)。同时覆盖 WriteString 后,5 种写法全部抓到。", t=tl(S(4)), mark=lidx(S(4), 'c.Writer.WriteString', 'io.WriteString(c.Writer'), done=lidx(S(4), 'c.String ', 'c.JSON ', 'c.Data '), b=bars([['只覆盖 Write:抓到的写法', 3, '3 / 5'], ['同时覆盖 WriteString:抓到的写法', 5, '5 / 5']], 5, mark=[0], done=[1]), kv=KV([['只覆盖 Write', '漏掉 WriteString 与 io.WriteString'], ['c.String / JSON / Data', '最终走 Write'], ['结论', '包装器两个方法都要覆盖']], ['结论'])),
    step("Hijack:正文写出之前可以,/before 里拿到 conn(err=nil)并手写了一个 200 \"hi\" 响应;/after 里先 c.String 并 Flush,再 Hijack 返回 err=gin: response body already written(size > 0 时拒绝),客户端收到的是已经写出的 200 \"already\"。", t=tl(S(5)), mark=lidx(S(5), 'err=gin: response body already written'), done=lidx(S(5), '写正文前 Hijack', '客户端收到 200 "hi"'), kv=KV([['写正文前', 'Hijack 成功'], ['写正文后', 'gin: response body already written'], ['size == 0', '只发了状态行时也允许']], ['写正文后'])),
]
A = mkartn('n24', 24, 'Gin,ResponseWriter,Status,Size,Written,Hijack,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 ResponseWriter:size = -1 表示未写出,WriteHeaderNow 后为 0;状态在写出前可以反复改、写出后锁定,debug 模式会打印警告;包装器只覆盖 Write 会漏掉 c.Writer.WriteString 与 io.WriteString;Hijack 在正文写出之后返回 gin: response body already written。',
    'c.Writer 不是 http.ResponseWriter 本身,而是 Gin 包了一层、记录状态和字节数的 responseWriter。这篇看这一层怎么工作:Status、Size、Written 在一次请求里如何变化,状态为什么写出后改不了,自己再包一层抓响应体时容易漏掉什么,以及 Hijack 的限制。',
    [('-1 → 0 → 11', 'Size() 的变化:未写出 -1,WriteHeaderNow 后 0,写完 hello world 后 11'), ('3 / 5', '只覆盖 Write 的包装器能抓到的写法个数(漏掉 WriteString 与 io.WriteString)'), ('already written', 'Hijack 在正文写出之后返回的错误:gin: response body already written')],
    [('size 与 status', '<p>Gin 用 <code>size = -1</code> 表示“还没写任何东西”,<code>WriteHeaderNow</code> 之后变成 0,每次写入再累加。<code>c.Status</code> 只是记录状态;状态行要等到第一次写正文或手工 <code>WriteHeaderNow</code> 才真正发出,之后再改就被忽略。</p>'),
     ('一次请求里的变化', '<p>handler 刚进入时 <code>Status()</code> 是默认的 200、<code>Size()</code> 是 -1、<code>Written()</code> 为 false;<code>c.Header</code> 不影响它们;<code>c.Status</code> 可以反复改;<code>WriteHeaderNow</code> 之后 <code>Size()</code> 变成 0、<code>Written()</code> 为 true、状态锁定,再写正文时 <code>Size()</code> 累加。注意 <code>Written()</code> 表示“状态行已发出”,不等于“写过正文”。</p>'),
     ('写出之后再改状态', '<p>状态行一旦发出就锁定。debug 模式下再改会打印“Headers were already written”的警告,release 模式下完全静默——线上排查“为什么状态码不对”时要想到这一点。</p>'),
     ('包装 ResponseWriter', '<p>日志、压缩、签名类中间件常常包装 <code>c.Writer</code> 来拦截响应体。<code>gin.ResponseWriter</code> 接口里 <code>WriteString</code> 是独立于 <code>Write</code> 的方法,所以只覆盖 <code>Write</code> 的包装器会漏掉直接调用 <code>c.Writer.WriteString</code> 或 <code>io.WriteString(c.Writer, …)</code> 的代码。<code>c.String</code>、<code>c.JSON</code>、<code>c.Data</code> 走的是 <code>Write</code>,所以不受影响。</p>'),
     ('Hijack 的限制', '<p>正文还没写出时可以 <code>Hijack</code> 拿到底层连接(WebSocket 的升级就是这么做的)。一旦写过正文(size &gt; 0),<code>Hijack</code> 返回 <code>gin: response body already written</code>,因为这时连接已经不干净了。</p>')],
    steps,
    [ENV_N_GIN + '。前三节用 httptest 直接调用 ServeHTTP(第三节用 GIN_MODE=debug);第四节同时覆盖了 5 种写法;第五节用真实的 httptest.NewServer 与 http.Client;每种情形各一次',
     '没有验证:Flush / Pusher / CloseNotify 经过包装器时的行为;压缩中间件(gzip)对 Size() 的影响;http.Hijacker 在 HTTP/2 下的情形(HTTP/2 不支持 Hijack,没有跑);其他版本的 responseWriter 实现'],
    'ResponseWriter')
